public class RecorrerArrays {
    public static void main(String[] args) {
        String[] nombres = {"Ana", "Carlos", "Maria", "Pedro", "Laura"};
        double[] notas = {8.5, 7.0, 9.2, 6.8, 8.0};

        // === Bucle for clasico ===
        System.out.println("=== Bucle for ===");
        for (int i = 0; i < nombres.length; i++) {
            System.out.println(nombres[i] + ": " + notas[i]);
        }

        // === Bucle for-each (enhanced for) ===
        System.out.println("\n=== Bucle for-each ===");
        for (String nombre : nombres) {
            System.out.println("Alumno: " + nombre);
        }

        // === Bucle for-each con notas ===
        System.out.println("\n=== Notas ===");
        for (double nota : notas) {
            System.out.printf("Nota: %.1f%n", nota);
        }

        // === Calcular la nota media ===
        double suma = 0;
        for (double nota : notas) {
            suma += nota;
        }
        double media = suma / notas.length;
        System.out.printf("\nNota media: %.2f%n", media);
    }
}

