        Alumno[] alumnos = {
            new Alumno("Ana", "ana@email.com"),
            new Alumno("Carlos", "carlos@email.com")
        };
        Alumno[] alumnosCopia = alumnos.clone();
        // ambas referencias apuntan al MISMO objeto
        System.out.println(alumnos[0] == alumnosCopia[0]); // true!

        // Para arrays de objetos, usa un bucle y crea nuevos objetos:
        Alumno[] alumnosCopiaReal = new Alumno[alumnos.length];
        for (int i = 0; i < alumnos.length; i++) {
