public class OrdenacionArrays {

    // === Selection Sort: busca el minimo y lo pone al inicio ===
    public static void selectionSort(int[] arr) {
        for (int i = 0; i < arr.length - 1; i++) {
            int minIdx = i;
            for (int j = i + 1; j < arr.length; j++) {
                if (arr[j] < arr[minIdx]) {
                    minIdx = j;
                }
            }
            // Intercambiar arr[i] con arr[minIdx]
            int temp = arr[i];
            arr[i] = arr[minIdx];
            arr[minIdx] = temp;
        }
    }

    // === Bubble Sort: burbuja elementos grandes al final ===
    public static void bubbleSort(int[] arr) {
        for (int i = 0; i < arr.length - 1; i++) {
            boolean intercambiado = false;
            for (int j = 0; j < arr.length - 1 - i; j++) {
                if (arr[j] > arr[j + 1]) {
                    int temp = arr[j];
                    arr[j] = arr[j + 1];
                    arr[j + 1] = temp;
                    intercambiado = true;
                }
            }
            if (!intercambiado) break;
        }
    }

    public static void mostrar(int[] arr) {
        for (int n : arr) System.out.print(n + " ");
        System.out.println();
    }

    public static void main(String[] args) {
        int[] nums1 = {64, 25, 12, 22, 11};
        int[] nums2 = {64, 25, 12, 22, 11};

        System.out.println("Selection Sort:");
        mostrar(nums1);
        selectionSort(nums1);
        mostrar(nums1);

        System.out.println("Bubble Sort:");
        mostrar(nums2);
        bubbleSort(nums2);
        mostrar(nums2);
    }
}

import java.util.Arrays;

public class ArraysSort {
    public static void main(String[] args) {
        // Arrays.sort() usa Dual-Pivot Quicksort (O(n log n))
        int[] numeros = {64, 25, 12, 22, 11};
        System.out.println("Antes: " + Arrays.toString(numeros));

        Arrays.sort(numeros);
        System.out.println("Despues: " + Arrays.toString(numeros));

        // Buscar en array ordenado con busqueda binaria
        int indice = Arrays.binarySearch(numeros, 22);
        System.out.println("22 encontrado en posicion: " + indice);

        // Arrays de strings
        String[] nombres = {"Pedro", "Ana", "Carlos", "Maria"};
        Arrays.sort(nombres);
        System.out.println("Nombres ordenados: " + Arrays.toString(nombres));

        // Copiar un array
        int[] copia = Arrays.copyOf(numeros, numeros.length);
        System.out.println("Copia: " + Arrays.toString(copia));
    }
}

