        String[] nombres = {"Ana", "Carlos", "Maria", "Pedro"};
        double[] notas = {8.5, 7.0, 9.2, 5.5};

        // Selection Sort por nota (descendente)
        for (int i = 0; i < notas.length - 1; i++) {
            int maxIdx = i;
            for (int j = i + 1; j < notas.length; j++) {
                if (notas[j] > notas[maxIdx]) {
