                System.out.printf("%8.1f", notas[i][j]);
            }
            System.out.println();
        }

        // 2. Media por alumno
        System.out.println("\n=== MEDIA POR ALUMNO ===");
        for (int i = 0; i < alumnos.length; i++) {
            double suma = 0;
            for (double n : notas[i]) suma += n;
            System.out.printf("%s: %.2f%n", alumnos[i], suma / notas[i].length);
        }

        // 3. Media por asignatura
        System.out.println("\n=== MEDIA POR ASIGNATURA ===");
        for (int j = 0; j < asignaturas.length; j++) {
            double suma = 0;
            for (int i = 0; i < alumnos.length; i++) suma += notas[i][j];
            System.out.printf("%s: %.2f%n", asignaturas[j], suma / alumnos.length);
        }
    }
